<script setup lang="ts">
const props=defineProps<{roleId?:number;create?:boolean}>()
const {t}=useI18n(),{roleLabel}=useOptionLabel(),{bizErrorMessage}=useBizError(),router=useRouter()
const roles=ref<any[]>([]),permissions=ref<any[]>([]),record=ref<any>(null),loading=ref(true),saving=ref(false),keyword=ref(''),error=ref(''),nameError=ref('')
const form=reactive({name:'',description:'',permissions:[] as number[],is_active:true})
const filtered=computed(()=>roles.value.filter(row=>(row.name+' '+row.description+' '+roleLabel(row.name)).toLowerCase().includes(keyword.value.toLowerCase())))
const load=async()=>{if(props.create){form.name='';form.description='';form.permissions=[];form.is_active=true;nameError.value=''}loading.value=true;error.value='';const results=await Promise.all([httpRequest<PaginationData>('/api/system/user/roles',{params:{per_page:999},onError:e=>error.value=bizErrorMessage(e)}),httpRequest<PaginationData>('/api/system/user/permissions',{params:{per_page:999},onError:e=>error.value=bizErrorMessage(e)})]);roles.value=results[0]?.items||[];permissions.value=results[1]?.items||[];if(!props.create){const id=props.roleId||roles.value[0]?.id;if(id){record.value=await httpRequest<any>('/api/system/user/roles/'+id,{onError:e=>error.value=bizErrorMessage(e)});if(record.value){form.is_active=record.value.is_active!==false;form.name=record.value.name;form.description=record.value.description||'';form.permissions=permissions.value.filter(p=>(record.value.permissions||[]).includes(p.name)).map(p=>p.id)}}}loading.value=false}
const save=async()=>{if(saving.value||loading.value||error.value)return;nameError.value=form.name.trim()?'':t('common.validation.name-required',{entity:t('common.entities.role')});if(nameError.value)return;saving.value=true;let saved:any=null;await httpRequest<any>('/api/system/user/roles'+(props.create?'':'/'+record.value.id),{method:props.create?'POST':'PUT',body:{name:form.name.trim(),description:form.description,permissions:form.permissions,is_active:form.is_active},onSuccess:data=>{saved=data},onError:e=>showToast(bizErrorMessage(e),'error')});if(saved){showToast(t('action-results.success'),'success');if(props.create&&saved.id)await router.push('/admin/roles/'+saved.id);else await load()}saving.value=false}
const remove=async()=>{if(!record.value||record.value.is_builtin||saving.value)return;if(!await showConfirm(t('action-results.delete-confirm-title'),t('action-results.delete-confirm',{entity:t('common.entities.role')}),t('button.confirm'),t('button.cancel')))return;saving.value=true;let deleted=false;await httpRequest('/api/system/user/roles/'+record.value.id,{method:'DELETE',onSuccess:()=>{deleted=true},onError:e=>showToast(bizErrorMessage(e),'error')});saving.value=false;if(deleted)await router.push('/admin/roles')}
onMounted(load)
useHead({title:()=>t('admin.nav.roles')})
</script>
<template><div class="w-role-manager w-scope"><header><h1>{{t('admin.nav.roles')}}</h1><WButton variant="primary" to="/admin/roles/add">{{t('admin.roles.operations.add')}}</WButton></header><WAlert v-if="error" tone="block" :title="error"/><div class="role-grid"><WCard flush><div class="search"><WInput v-model="keyword" type="search" :aria-label="t('common.search')" :placeholder="t('common.search-placeholder')"><template #prefix><WIcon name="search" :size="16"/></template></WInput></div><nav class="role-list"><NuxtLink v-for="row in filtered" :key="row.id" class="w-role-link" :class="{selected:record?.id===row.id}" :to="'/admin/roles/'+row.id"><strong>{{roleLabel(row.name)}}</strong><code v-if="roleLabel(row.name)!==row.name">{{row.name}}</code><small>{{row.description}}</small><span v-if="row.is_builtin" class="builtin">{{t('admin.builtin.label')}}</span></NuxtLink></nav></WCard><WCard flush><div class="form-heading"><h2>{{create?t('admin.roles.operations.add'):roleLabel(record?.name)}}</h2><span v-if="record?.is_builtin" class="builtin">{{t('admin.builtin.label')}}</span></div><WEmptyState v-if="loading" :title="t('common.status.loading')"/><form v-else-if="create||record" @submit.prevent="save"><fieldset :disabled="saving||!!error"><section class="form-section"><div class="fields"><WField :label="t('common.fields.name')" required :error="nameError" :hint="record?.is_builtin?t('admin.builtin.role-tip'):undefined"><WInput v-model="form.name" :readonly="record?.is_builtin"/></WField><WField :label="t('common.fields.description')"><WInput v-model="form.description"/></WField><WSwitch v-model="form.is_active" :disabled="record?.is_builtin">{{t('recipient.ui.enable')}}</WSwitch></div></section><section class="permissions"><PermissionSelector matrix :all-permissions="permissions" v-model="form.permissions"/></section></fieldset><footer><WButton v-if="record&&!record.is_builtin" variant="danger" :disabled="saving" @click="remove">{{t('button.delete')}}</WButton><WButton :disabled="saving" @click="load">{{t('button.reset')}}</WButton><WButton type="submit" variant="primary" :loading="saving" :disabled="!!error">{{t('button.save')}}</WButton></footer></form></WCard></div></div></template>
<style scoped>
.w-role-manager{display:flex;flex-direction:column;gap:16px}header{display:flex;align-items:center;justify-content:space-between;gap:12px}h1{font-size:24px;line-height:32px;font-weight:600;margin:0}.role-grid{display:grid;grid-template-columns:256px minmax(0,1fr);gap:16px;align-items:start}.search{padding:12px;border-bottom:1px solid var(--w-line)}.role-list{padding:8px;display:flex;flex-direction:column;gap:2px}.w-role-link{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;padding:8px 12px;border-radius:6px;color:var(--w-text-1);text-decoration:none}.w-role-link.selected{background:#F5F4FF;color:#4E1DBC}.w-role-link strong{font-size:14px;line-height:22px;font-weight:500}.w-role-link.selected strong{font-weight:600}code,small{font-size:12px;line-height:18px;color:var(--w-text-3)}small{flex-basis:100%}.builtin{display:inline-block;padding:1px 6px;border:1px solid var(--w-border);border-radius:6px;font-size:12px;line-height:16px;color:var(--w-text-2)}.form-heading{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:16px 24px 4px}h2{font-size:16px;line-height:24px;font-weight:600;margin:0}h3{font-size:14px;line-height:22px;font-weight:600;margin:0}fieldset{border:0;padding:0;margin:0;min-width:0}.form-section{padding:12px 24px 20px}.fields{display:grid;grid-template-columns:1fr 2fr;gap:12px 16px}.fields>.w-switch{grid-column:1/-1}.permissions{padding:0}footer{display:flex;justify-content:flex-end;gap:8px;padding:16px 24px;border-top:1px solid var(--w-border)}@media(max-width:1100px){.role-grid{grid-template-columns:minmax(0,1fr)}.role-list{max-height:240px;overflow:auto}.form-section{grid-template-columns:minmax(0,1fr);gap:16px}}
@media(max-width:600px){.fields{grid-template-columns:minmax(0,1fr)}header,footer{flex-wrap:wrap}}
</style>
